    private void TestCompare2()
    {
        Stopwatch sw = Stopwatch.StartNew();
        sw.Start();

        using var faceImage0 = SKBitmap.Decode("C:\\Users\\thanh\\Downloads\\duc1.jpg").ToFaceImage();
        using var faceImage1 = SKBitmap.Decode("C:\\Users\\thanh\\Downloads\\duc2.jpg").ToFaceImage();
        //检测人脸信息
        using FaceDetector faceDetector = new FaceDetector();
        FaceInfo[] infos0 = faceDetector.Detect(faceImage0);
        FaceInfo[] infos1 = faceDetector.Detect(faceImage1);
        //标记人脸位置
        using FaceLandmarker faceMark = new FaceLandmarker();
        FaceMarkPoint[] points0 = faceMark.Mark(faceImage0, infos0[0]);
        FaceMarkPoint[] points1 = faceMark.Mark(faceImage1, infos1[0]);
        //提取特征值
        using FaceRecognizer faceRecognizer = new FaceRecognizer();
        float[] data0 = faceRecognizer.Extract(faceImage0, points0);
        float[] data1 = faceRecognizer.Extract(faceImage1, points1);
        //对比特征值
        bool isSelf = faceRecognizer.IsSelf(data0, data1);
        var score = faceRecognizer.Compare(data0, data1) * 100;
        Console.WriteLine($"识别到的人脸是否为同一人：{isSelf}，对比耗时：{sw.ElapsedMilliseconds}ms");
        Console.WriteLine();
        sw.Stop();
    }
    private void TestCompare()
    {
        try
        {
            FaceRecognizeConfig _FaceRecConfig = new FaceRecognizeConfig();
            _FaceRecConfig.SetThreshold(FaceType.Normal, (float)85 / (float)100);

            using FaceDetector _FaceDetector = new FaceDetector();
            using FaceRecognizer _FaceRecognizer = new FaceRecognizer(_FaceRecConfig);


            Mat mImg1 = Cv2.ImRead("C:\\Users\\thanh\\Downloads\\duc1.jpg");
            Mat mImg2 = Cv2.ImRead("C:\\Users\\thanh\\Downloads\\duc2.jpg");
            var skBitmap1 = SKBitmap.Decode(mImg1.ToBytes());
            var skBitmap2 = SKBitmap.Decode(mImg2.ToBytes());
            using var skImage1 = skBitmap1.ToFaceImage();
            using var skImage2 = skBitmap2.ToFaceImage();
            var infos1 = _FaceDetector.Detect(skImage1);
            var infos2 = _FaceDetector.Detect(skImage2);

            using FaceLandmarker faceMark = new FaceLandmarker();
            FaceMarkPoint[] points1 = faceMark.Mark(skBitmap1, infos1[0]);
            FaceMarkPoint[] points2 = faceMark.Mark(skBitmap2, infos2[0]);
            float[] dataExt1 = _FaceRecognizer.Extract(skBitmap1, points1);
            float[] dataExt2 = _FaceRecognizer.Extract(skBitmap2, points2);
            int compareValue = (int)(_FaceRecognizer.Compare(dataExt1, dataExt2) * 100);
        }
        catch (Exception e)
        {
            e.ToString();
        }
    }

