    private void timer1_Tick(object sender, EventArgs e)
    {
        btnConvert_Click(sender, e);
    }

    private void textBox1_TextChanged(object sender, EventArgs e)
    {
        try
        {
            pictureBox1.Image = null;
            var bts = Convert.FromBase64String(textBox1.Text);
            using (var ms = new MemoryStream(bts))
            {
                pictureBox1.Image = Image.FromStream(ms);
            }
        } catch (Exception) { }
    }

    private void textBox2_TextChanged(object sender, EventArgs e)
    {
        try
        {
            pictureBox2.Image = null;
            var bts = Convert.FromBase64String(textBox2.Text);
            using (var ms = new MemoryStream(bts))
            {
                pictureBox2.Image = Image.FromStream(ms);
            }
        }
        catch (Exception) { }
    }

    private void btnConvert_Click(object sender, EventArgs e)
    {
        try
        {
            ImageConverter converter = new ImageConverter();
            var bts1 = (byte[])converter.ConvertTo(pictureBox1.Image, typeof(byte[]));
            var bts2 = (byte[])converter.ConvertTo(pictureBox2.Image, typeof(byte[]));
            textBox1.Text = Convert.ToBase64String(bts1);
            textBox2.Text = Convert.ToBase64String(bts2);
        }
        catch (Exception)
        {
        }
    }
